    if(options.value!==undefined)input.value=options.value;if(options.placeholder)input.placeholder=options.placeholder;
    if(options.min!==undefined)input.min=options.min;if(options.max!==undefined)input.max=options.max;if(options.step!==undefined)input.step=options.step;if(options.pattern)input.pattern=options.pattern;
