    formField(form,grid,'game_id','Canonical fixture ID',{required:true,placeholder:'YYYY_WW_AWAY_HOME'});formField(form,grid,'market','Market',{required:true,options:[['receiving_yards','Receiving yards'],['rushing_yards','Rushing yards']]});
    formField(form,grid,'side','Side',{required:true,options:[['','Select a side'],['OVER','Over'],['UNDER','Under']]});formField(form,grid,'line','Exact offered line',{required:true,type:'number',step:'0.5'});
    formField(form,grid,'decimal_odds','Actual decimal price',{required:true,type:'number',min:'1.001',step:'0.001'});formField(form,grid,'stake_units','User-stated stake (units)',{required:true,type:'number',min:'0.001',step:'0.001'});
    formField(form,grid,'bookmaker','Bookmaker',{required:true});formField(form,grid,'offer_id','Unique offer ID',{required:true});
    formField(form,grid,'captured_at','Offer captured at (UTC)',{required:true,placeholder:'YYYY-MM-DDTHH:mm:ssZ'});formField(form,grid,'selected_at','Selection recorded at (UTC)',{required:true,placeholder:'YYYY-MM-DDTHH:mm:ssZ'});
    formField(form,grid,'kickoff','Kickoff (UTC)',{required:true,placeholder:'YYYY-MM-DDTHH:mm:ssZ'});formField(form,grid,'strategy_version','Strategy / algorithm version',{required:true,value:'manual-accounting-v1'});
    const hash=formField(form,grid,'offer_raw_sha256','Original offer evidence SHA256',{pattern:'[a-f0-9]{64}',placeholder:'64 lowercase hexadecimal characters',wide:true,hint:'Required for REAL. Keep the original offer artifact in your private evidence store.'});
