    const attestLabel=el('label','field check wide'),attest=el('input');attest.type='checkbox';attest.name='user_attested_placed';add(attestLabel,attest,el('span','','I personally attest this REAL wager was already placed and the offer evidence is authentic.'));add(grid,attestLabel);
    const sync=()=>{const real=mode.value==='REAL';hash.required=real;rules.required=real;attest.required=real;attestLabel.hidden=!real;if(real)placement.value='PLACED';placement.disabled=real;};mode.addEventListener('change',sync);sync();
